12	export class BasicTransport implements IConnectionTransport {
13	  private subscriptions = new ConnectionSubscriptions();
14	  private producer?: MessageProducer;
15	
16	  static withProducerCallback(producer: MessageProducer): IConnectionTransport {
17	    return new BasicTransport(producer);
18	  }
