25	    this.producer = producer;
26	  }
27	
28	  private startProducer() {
29	    if (this.producer) {
30	      this.producer((message) => {
31	        this.subscriptions.notify("message", message);
32	      });
33	    }
34	  }
35	
36	  private connect(): Promise<void> {
37	    return new Promise<void>((resolve) => setTimeout(resolve, 0)).then(() => {
38	      this.subscriptions.notify("open", new Event("open"));
39	    });
40	  }
