3	import { afterEach, describe, expect, it, vi } from "vitest";
4	import { Logger } from "@/utils/Logger";
5	import { WebSocketClosedReason, WebSocketState } from "../types";
6	import { classifyCloseEvent } from "../useMarimoKernelConnection";
7	import { MAX_RETRIES } from "../useWebSocket";
8	
9	function classify(
10	  reason: string | undefined,
11	  retryCount = 0,
12	  maxRetries = MAX_RETRIES,
13	) {
14	  return classifyCloseEvent({ reason }, { retryCount, maxRetries });
15	}
16	
17	describe("classifyCloseEvent", () => {
18	  describe("transient closes (default branch)", () => {
19	    it("retries when retryCount < maxRetries", () => {
20	      const decision = classify(undefined, 0);
21	      expect(decision.kind).toBe("retry");
22	      expect(decision.status).toEqual({ state: WebSocketState.CONNECTING });
23	    });
24	
25	    it("retries on each intermediate close event during a retry storm", () => {
26	      for (let n = 0; n < MAX_RETRIES; n++) {
27	        const decision = classify(undefined, n);
28	        expect(decision.kind).toBe("retry");
29	        expect(decision.status).toEqual({ state: WebSocketState.CONNECTING });
30	      }
31	    });
32	
33	    it("transitions to CLOSED when retryCount reaches maxRetries", () => {
34	      const decision = classify(undefined, MAX_RETRIES);
35	      expect(decision.kind).toBe("gave-up");
36	      expect(decision.status).toEqual({
37	        state: WebSocketState.CLOSED,
38	        code: WebSocketClosedReason.KERNEL_DISCONNECTED,
39	        reason: "kernel not found",
40	      });
41	    });
42	
43	    it("transitions to CLOSED when retryCount exceeds maxRetries", () => {
44	      const decision = classify(undefined, MAX_RETRIES + 5);
45	      expect(decision.kind).toBe("gave-up");
46	    });
47	
48	    it("treats unknown reason strings as transient and logs a warning", () => {
49	      const logger = vi.spyOn(Logger, "warn").mockImplementation(() => {});
50	      const decision = classify("something-else", 3);
51	      expect(decision.kind).toBe("retry");
52	      expect(logger).toHaveBeenCalled();
53	      logger.mockRestore();
54	    });
55	  });
56	
57	  afterEach(() => {
58	    vi.restoreAllMocks();
59	  });
60	
61	  describe("terminal closes (server-initiated)", () => {
62	    it("MARIMO_ALREADY_CONNECTED → terminal + closeTransport, with takeover", () => {
63	      const decision = classify("MARIMO_ALREADY_CONNECTED", 0);
64	      expect(decision.kind).toBe("terminal");
65	      expect(decision.status).toMatchObject({
66	        state: WebSocketState.CLOSED,
67	        code: WebSocketClosedReason.ALREADY_RUNNING,
68	        canTakeover: true,
69	      });
70	      if (decision.kind === "terminal") {
71	        expect(decision.closeTransport).toBe(true);
72	      }
73	    });
74	
75	    it.each([
76	      "MARIMO_WRONG_KERNEL_ID",
77	      "MARIMO_NO_FILE_KEY",
78	      "MARIMO_NO_SESSION_ID",
79	      "MARIMO_NO_SESSION",
80	      "MARIMO_SHUTDOWN",
81	    ])("%s → terminal with KERNEL_DISCONNECTED, closes transport", (reason) => {
82	      const decision = classify(reason, 0);
83	      expect(decision.kind).toBe("terminal");
84	      expect(decision.status).toMatchObject({
85	        state: WebSocketState.CLOSED,
86	        code: WebSocketClosedReason.KERNEL_DISCONNECTED,
87	      });
88	      if (decision.kind === "terminal") {
89	        expect(decision.closeTransport).toBe(true);
90	      }
91	    });
92	
93	    it("MARIMO_MALFORMED_QUERY → terminal but does NOT close transport", () => {
94	      const decision = classify("MARIMO_MALFORMED_QUERY", 0);
95	      expect(decision.kind).toBe("terminal");
96	      expect(decision.status).toMatchObject({
97	        state: WebSocketState.CLOSED,
98	        code: WebSocketClosedReason.MALFORMED_QUERY,
99	      });
100	      if (decision.kind === "terminal") {
101	        expect(decision.closeTransport).toBe(false);
102	      }
103	    });
104	
105	    it("MARIMO_KERNEL_STARTUP_ERROR → terminal + closeTransport", () => {
106	      const decision = classify("MARIMO_KERNEL_STARTUP_ERROR", 0);
107	      expect(decision.kind).toBe("terminal");
108	      expect(decision.status).toMatchObject({
109	        state: WebSocketState.CLOSED,
110	        code: WebSocketClosedReason.KERNEL_STARTUP_ERROR,
111	      });
112	      if (decision.kind === "terminal") {
113	        expect(decision.closeTransport).toBe(true);
114	      }
115	    });
116	
117	    it("terminal closes ignore retryCount entirely", () => {
118	      const decision = classify("MARIMO_SHUTDOWN", 99);
119	      expect(decision.kind).toBe("terminal");
120	    });
121	  });
122	
123	  describe("retry budget exhaustion", () => {
124	    it("yields retry on attempts 1..maxRetries-1 and gave-up on the final close", () => {
125	      const states: string[] = [];
126	      for (let attempt = 1; attempt <= MAX_RETRIES; attempt++) {
127	        states.push(classify(undefined, attempt - 1).kind);
128	      }
129	      states.push(classify(undefined, MAX_RETRIES).kind);
130	
131	      expect(states).toEqual([
132	        ...Array.from({ length: MAX_RETRIES }, () => "retry"),
133	        "gave-up",
134	      ]);
135	    });
136	  });
137	});
