import ReconnectingWebSocket from "partysocket/ws";
import type {
  ConnectionEvent,
  ConnectionTransportCallback,
  IConnectionTransport,
} from "./transport";

// Per-`reconnect()` retry budget for partysocket. After exhaustion, partysocket
// stops silently, so we surface the give-up ourselves by rewriting the close
// reason (see below).
export const MAX_RETRIES = 10;

// Synthetic close reason injected once the retry budget is exhausted.
// `classifyCloseEvent` recognizes this as the terminal "gave-up" signal.
export const TRANSPORT_EXHAUSTED_REASON = "MARIMO_TRANSPORT_EXHAUSTED";

/**
 * A connection transport that wraps partysocket's {@link ReconnectingWebSocket}.
 *
 * partysocket stops retrying silently once `maxRetries` is hit. To make the
 * give-up observable, this transport intercepts close events: when the inner
 * socket has exhausted its retry budget, it rewrites the close event's reason
 * to {@link TRANSPORT_EXHAUSTED_REASON} before forwarding it to listeners. This
 * rewrite takes precedence over any server-sent reason.
 */
export class WsTransport implements IConnectionTransport {
  private readonly inner: ReconnectingWebSocket;

  // Maps each user-registered callback to the wrapper that was actually
  // registered on the inner socket, keyed by event type. Using a Map keyed by
  // the original callback deduplicates registrations and lets a single
  // `removeEventListener` call fully unregister the callback.
  private readonly wrappers = new Map<
    ConnectionEvent,
    Map<ConnectionTransportCallback<ConnectionEvent>, (event: Event) => void>
  >();

  constructor(urlFactory: () => string) {
    // We pass the URL factory (not a string) since the URL may change if the
    // runtime redirects.
    this.inner = new ReconnectingWebSocket(urlFactory, undefined, {
      maxRetries: MAX_RETRIES,
      debug: false,
      startClosed: true,
      // long timeout -- the server can become slow when many notebooks
      // are open.
      connectionTimeout: 10_000,
    });
  }

  get readyState(): WebSocket["readyState"] {
    // ReconnectingWebSocket types readyState as `number`.
    return this.inner.readyState as WebSocket["readyState"];
  }

  get retryCount(): number {
    return this.inner.retryCount;
  }

  reconnect(code?: number | undefined, reason?: string | undefined): void {
    this.inner.reconnect(code, reason);
  }

  close(): void {
    this.inner.close();
  }

  send(data: string | ArrayBuffer | Blob | ArrayBufferView): void {
    this.inner.send(data);
  }

  addEventListener<T extends ConnectionEvent>(
    event: T,
    callback: ConnectionTransportCallback<T>,
  ): void {
    const cb = callback as ConnectionTransportCallback<ConnectionEvent>;
    let perEvent = this.wrappers.get(event);
    if (!perEvent) {
      perEvent = new Map();
      this.wrappers.set(event, perEvent);
    }
    // Deduplicate: adding the same callback twice must not fire it twice.
    if (perEvent.has(cb)) {
      return;
    }

    const wrapper = (rawEvent: Event) => {
      if (event === "close") {
        cb(this.maybeRewriteClose(rawEvent as CloseEvent) as never);
      } else {
        cb(rawEvent as never);
      }
    };
    perEvent.set(cb, wrapper);
    // Cast to the string-typed overload; the wrapper handles all event types.
    (
      this.inner.addEventListener as (
        type: string,
        callback: (event: Event) => void,
      ) => void
    )(event, wrapper);
  }

  removeEventListener<T extends ConnectionEvent>(
    event: T,
    callback: ConnectionTransportCallback<T>,
  ): void {
    const cb = callback as ConnectionTransportCallback<ConnectionEvent>;
    const perEvent = this.wrappers.get(event);
    const wrapper = perEvent?.get(cb);
    if (!perEvent || !wrapper) {
      return;
    }
    this.inner.removeEventListener(
      event,
      wrapper as (event: WebSocketEventMap[T]) => void,
    );
    perEvent.delete(cb);
  }

  /**
   * Rewrite the close reason to {@link TRANSPORT_EXHAUSTED_REASON} when the
   * inner socket has exhausted its retry budget. Otherwise the original event
   * is forwarded unchanged.
   */
  private maybeRewriteClose(event: CloseEvent): CloseEvent {
    if (this.inner.retryCount < MAX_RETRIES) {
      return event;
    }
    return new CloseEvent(event.type, {
      code: event.code,
      reason: TRANSPORT_EXHAUSTED_REASON,
      wasClean: event.wasClean,
    });
  }
}
